INSERT INTO team_members (name, role, photo, bio, is_ceo, sort_order) VALUES ('Olopade Yetunde', 'Chief Executive Officer', 'images/team/yetunde.jpg', 'A seasoned expert in events marketing, sponsorship activation, and brand partnerships with over 20 years of experience. Yetunde specialises in large-scale sports events, corporate collaborations, and impactful brand engagements — driving Nilayo\'s strategic vision and setting industry benchmarks in sports marketing across Africa.', 1, 0);
INSERT INTO team_members (name, role, photo, bio, is_ceo, sort_order) VALUES ('Olopade Adenike', 'Chief Operating Officer', 'images/team/adenike.jpg', 'The operational architect behind NSML\'s growth. Adenike ensures that every sponsorship commitment, event logistics plan, and client relationship is executed to the highest standard. She brings the same precision to a community 10KM race as to a World Athletics-certified marathon — because NSML\'s reputation is built on delivery, every single time.', 0, 1);
INSERT INTO team_members (name, role, photo, bio, is_ceo, sort_order) VALUES ('Odeh Emmanuel', 'Project Lead', 'images/team/emmanuel.jpg', 'A results-driven professional with expertise in business development, entrepreneurship, and team leadership. With extensive experience in project execution, Emmanuel drives business growth and operational efficiency. Backed by certifications in Business Administration and Management, his strategic vision and hands-on leadership make him a key asset in project management and business development at Nilayo.', 0, 2);
INSERT INTO team_members (name, role, photo, bio, is_ceo, sort_order) VALUES ('Adekite Bolaji', 'Admin', 'images/team/bolaji.jpg', 'An experienced HR professional with a BA in English Language, an MBA, and multiple professional certifications. Bolaji specialises in talent management, employee relations, and organisational development — nurturing a dynamic work environment. Committed to excellence and innovation, she drives Nilayo Sports\' success by attracting and developing top talent.', 0, 3);
INSERT INTO team_members (name, role, photo, bio, is_ceo, sort_order) VALUES ('Odi Jide', 'Brand & Comms Lead', 'images/team/jide.jpg', 'A seasoned media and communications professional with expertise in broadcast journalism, brand strategy, creative advertising, and media production. With over a decade of experience, Jide blends analytical insight with creative storytelling to strengthen Nilayo\'s brand presence. A trained journalist from the Nigerian Institute of Journalism and an alumnus of O2 Academy Lagos, he plays a key role in shaping the company\'s communication and marketing strategies.', 0, 4);
INSERT INTO team_members (name, role, photo, bio, is_ceo, sort_order) VALUES ('Omoniyi Sandra', 'Business Strategist', 'images/team/sandra.jpg', 'A specialist in sports management, strategy, and operations with a Master\'s in Sport Management and Administration and over a decade of experience. Sandra develops strategic solutions that drive revenue and brand growth, excels in forging high-impact partnerships, and creates sustainable business models that elevate sports properties. She combines strategic insight with deep industry expertise to deliver innovative solutions for brands and stakeholders.', 0, 5);

INSERT INTO properties (slug, title, tag, badge, hero_image, logo_image, description, stat1_val, stat1_lbl, stat2_val, stat2_lbl, stat3_val, stat3_lbl, detail_url, is_featured, is_upcoming, sort_order) VALUES (
  'lagos-marathon', 'Access Bank Lagos City Marathon', 'Flagship Property', 'World Athletics', 'images/events/lagos/lagos-card.jpg', 'images/events/ablcm-logo-[no-year].png', 'Africa\'s Strongest Marathon Brand 2025 — a World Athletics Global Certification. The 10th anniversary edition delivered in 2025 drew participation from across the globe, backed by Access Bank, KIA Motors, Seven Up, Aquafina, and Airtel. Raises over ₦3 billion annually from the private sector since its inception in 2016.', '440K+', 'Participants since 2016', '₦3B+', 'Raised annually', 'Feb 2027', 'Next edition', 'lagos-marathon.html', 1, 0, 0
);
