  'abuja-marathon', 'PremiumTrust Bank Abuja City International Half Marathon', 'International', NULL, 'images/events/abuja-hero.jpg', 'images/events/abj-logo-new.png', 'The capital\'s premier long-distance race. Inaugural edition April 2024 with 50,000+ participants. Backed by PremiumTrust Bank, Dana Airlines, Seven Up, Aquafina, and the AFN.', '50K+', 'Participants', 'Nov 2026', 'Next edition', NULL, NULL, 'abuja-marathon.html', 0, 0, 1
);
